From 6d67618d6af14094c445174b2eb5cd870d0e8122 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:55:54 +0100
Subject: [PATCH] handlebuttonevents: name the power button shortcuts after the
 button

The Shortcuts page listed "Power Off" and "Power Down", which read like
two names for the same thing although one is the power button press and
the other its long press. Name them "Power Button" and its long press.

BUG: 425915
---
 daemon/actions/bundled/handlebuttonevents.cpp | 4 ++--
 1 file changed, 2 insertions(+), 2 deletions(-)

diff --git a/daemon/actions/bundled/handlebuttonevents.cpp b/daemon/actions/bundled/handlebuttonevents.cpp
index 5d8a9e753..ab0168bea 100644
--- a/daemon/actions/bundled/handlebuttonevents.cpp
+++ b/daemon/actions/bundled/handlebuttonevents.cpp
@@ -58,7 +58,7 @@ HandleButtonEvents::HandleButtonEvents(QObject *parent)
     connect(globalAction, &QAction::triggered, this, &HandleButtonEvents::hibernate);

     globalAction = actionCollection->addAction(u"PowerOff"_s);
-    globalAction->setText(i18nc("@action:inmenu Global shortcut", "Power Off"));
+    globalAction->setText(i18nc("@action:inmenu Global shortcut", "Power Button"));
     auto powerButtonMode = [globalAction](bool isTablet) {
         if (!isTablet) {
             KGlobalAccel::self()->setGlobalShortcut(globalAction, Qt::Key_PowerOff);
@@ -72,7 +72,7 @@ HandleButtonEvents::HandleButtonEvents(QObject *parent)
     connect(globalAction, &QAction::triggered, this, &HandleButtonEvents::powerOffButtonTriggered);

     globalAction = actionCollection->addAction(u"PowerDown"_s);
-    globalAction->setText(i18nc("@action:inmenu Global shortcut, used for long presses of the power button", "Power Down"));
+    globalAction->setText(i18nc("@action:inmenu Global shortcut, used for long presses of the power button", "Power Button Long Press"));
     accel->setGlobalShortcut(globalAction, Qt::Key_PowerDown);
     connect(globalAction, &QAction::triggered, this, &HandleButtonEvents::powerDownButtonTriggered);

-- 
